setup-script.content:
// Setup script for demo data
// Execute: sf apex run --file scripts/setup.apex

// Example: Create sample accounts
List<Account> accounts = new List<Account>();
for (Integer i = 1; i <= 10; i++) {
    accounts.add(new Account(
        Name = 'Demo Account ' + i,
        Industry = 'Technology'
    ));
}
insert accounts;
System.debug('Created ' + accounts.size() + ' demo accounts');

deploy-script.content:
#!/bin/bash
# Deployment script

set -e

echo "Deploying to Salesforce..."

# Deploy source
sf project deploy start --target-org {{ORG_ALIAS}}

echo "Deployment complete!"

# Open org
sf org open --target-org {{ORG_ALIAS}}

